// §13c query 1 — any call or type reference from Domain/Session into Presentation,
// or from Presentation into Domain/Session. Both directions are forbidden by §9:
// Domain and Session never see Presentation, and Presentation never sees Domain.
// The asmdefs already make this fail to compile (§13a); this query catches it in
// review before the assemblies are wired, and proves the boundary held.
//
// Expected result: zero rows. Any row is a §9 violation — publish an event and
// route it through an Orchestrator (§6) instead of referencing across.
MATCH (a:Class|Struct|Interface|Enum|Method|Function|Constructor|Property|Const)
      -[r:CodeRelation]->
      (b:Class|Struct|Interface|Enum|Method|Function|Constructor|Property|Const)
WHERE r.type IN ['CALLS', 'USES', 'EXTENDS', 'ACCESSES', 'METHOD_OVERRIDES']
  AND (
        (
          (a.filePath STARTS WITH 'Assets/Scripts/Domain/'
            OR a.filePath STARTS WITH 'Assets/Scripts/Session/')
          AND b.filePath STARTS WITH 'Assets/Scripts/Presentation/'
        )
        OR
        (
          a.filePath STARTS WITH 'Assets/Scripts/Presentation/'
          AND (b.filePath STARTS WITH 'Assets/Scripts/Domain/'
            OR b.filePath STARTS WITH 'Assets/Scripts/Session/')
        )
      )
RETURN a.filePath AS from_file, a.name AS from_symbol, r.type AS edge,
       b.filePath AS to_file, b.name AS to_symbol
ORDER BY from_file, from_symbol

// §13c query 2 — any cycle among Domain systems, using each system's folder as the
// node. §2c requires the dependency graph inside a layer to be acyclic: if two
// systems need each other, the shared piece moves down (a Core DTO) or the
// coordination moves up (a Session Manager).
//
// This finds DIRECT (two-system) cycles, which is the case that actually occurs.
// Longer cycles (A -> B -> C -> A) need `gitnexus check` or a manual read of the
// header DEPENDENCIES lists.
//
// Expected result: zero rows.
MATCH (a:Class|Struct|Interface|Enum|Method|Function|Constructor|Property|Const)
      -[r:CodeRelation]->
      (b:Class|Struct|Interface|Enum|Method|Function|Constructor|Property|Const)
WHERE r.type IN ['CALLS', 'USES', 'EXTENDS', 'ACCESSES']
  AND a.filePath STARTS WITH 'Assets/Scripts/Domain/'
  AND b.filePath STARTS WITH 'Assets/Scripts/Domain/'
WITH string_split(a.filePath, '/')[4] AS system_a,
     string_split(b.filePath, '/')[4] AS system_b
WHERE system_a <> system_b
WITH DISTINCT system_a, system_b
WITH collect([system_a, system_b]) AS edges
UNWIND edges AS forward
UNWIND edges AS backward
WITH forward[1] AS system_a, forward[2] AS system_b, backward[1] AS back_a, backward[2] AS back_b
WHERE system_a = back_b AND system_b = back_a AND system_a < system_b
RETURN DISTINCT system_a, system_b
ORDER BY system_a, system_b

// §13c query 3 — any Driver-layer file that calls a Manager, Controller or Registry.
// §7a: a Driver never pulls game state. Data flows in as primitive command
// parameters, its DriverConfig, or a read-only view its Manager hands it; data
// flows out only as C# events. A Driver that calls into a game system has
// inverted the ownership direction (§9, rung 4).
//
// Expected result: zero rows. The fix is always the same: let the Manager push
// the value in, or let the Driver publish an event the Manager subscribes to.
MATCH (a:Class|Struct|Method|Function|Constructor|Property)
      -[r:CodeRelation]->
      (b:Class|Struct|Method|Function|Constructor|Property)
WHERE r.type IN ['CALLS', 'USES', 'ACCESSES']
  AND a.filePath STARTS WITH 'Assets/Scripts/'
  AND a.filePath CONTAINS '/Driver/'
  AND (
        b.name ENDS WITH 'Manager'
        OR b.name ENDS WITH 'Controller'
        OR b.name ENDS WITH 'Registry'
      )
  AND NOT b.filePath CONTAINS '/Driver/'
RETURN a.filePath AS driver_file, a.name AS driver_symbol, r.type AS edge,
       b.name AS reached_symbol, b.filePath AS reached_file
ORDER BY driver_file, driver_symbol

// §13c query 4 — any Orchestrator whose method bodies exceed a handful of statements.
// §6: an Orchestrator is stateless and thin. Each handler translates a payload and
// forwards it, one to three lines. If it needs to remember anything, that memory is
// a phase in the originating system's BehaviorState, not a field here.
//
// Line span is a proxy for statement count; 12 lines is the "handful" threshold and
// is deliberately generous. A hit is a prompt to read the method, not an automatic
// failure — but a genuinely fat Orchestrator method is logic that belongs in the
// system that published the event.
MATCH (m:Method)
WHERE m.filePath STARTS WITH 'Assets/Scripts/Orchestrator/'
  AND m.endLine - m.startLine > 12
RETURN m.filePath AS file, m.name AS method,
       m.startLine AS start_line, m.endLine - m.startLine AS line_span
ORDER BY line_span DESC

